    std::size_t coincidencias = 0;
    for (std::size_t i = 1; i < ordenados.size(); ++i) {
        if (ordenados[i] == ordenados[i - 1]) { ++coincidencias; }
    }
    std::cout << "Égaux au précédent :" << coincidencias
              << "\nN :" << ordenados.size() << "\n";
    return 0;
}

